1	/**
2	 * Node.js port of `test4.py`.
3	 *
4	 *     node test4.mjs --a <hrp> --b <witness version> --c <comma-separated bytes>
5	 *
6	 * Prints the encoded segwit address, or `None` when the reference `bech32`
7	 * package refuses to encode the inputs.  Failures reproduce the frozen Python
8	 * build's behaviour: argparse errors exit 2 with usage on stderr, and an
9	 * unhandled Python exception exits 1 with a traceback.
10	 */
11	
12	import * as bech32 from './lib/bech32/index.mjs';
13	import { ArgumentParser } from './lib/py/argparse.mjs';
14	import { PythonError } from './lib/py/errors.mjs';
15	import { pythonInt } from './lib/py/int.mjs';
16	import {
17	  CONVERT_ARGUMENT_FRAMES,
18	  ENCODE_FRAMES,
19	  reportUnhandledException,
20	} from './lib/py/traceback.mjs';
21	import { writeStdout } from './lib/py/stdio.mjs';
22	
23	const PROGRAM_NAME = 'test4_executable';
24	
25	/** Runs `step`, reporting a Python exception through `frames` and exiting 1. */
26	function frozen(frames, step) {
27	  try {
28	    return step();
29	  } catch (error) {
30	    if (error instanceof PythonError) {
31	      reportUnhandledException(error, frames);
32	      process.exit(1);
33	    }
34	    throw error;
35	  }
36	}
37	
38	function main() {
39	  const parser = new ArgumentParser({ prog: PROGRAM_NAME });
40	  parser.add_argument('--a', { typeName: 'str', required: true }); // HRP
41	  parser.add_argument('--b', { type: pythonInt, typeName: 'int', required: true }); // Witness version
42	  parser.add_argument('--c', { typeName: 'str', required: true }); // Witness program as comma-separated integers
43	  const args = parser.parse_args(process.argv.slice(2));
44	
45	  const witprog = frozen(CONVERT_ARGUMENT_FRAMES, () =>
46	    args.c.split(',').map((piece) => pythonInt(piece)),
47	  );
48	  const result = frozen(ENCODE_FRAMES, () =>
49	    bech32.encode(args.a, args.b, witprog),
50	  );
51	  // `print(None)` writes "None".
52	  writeStdout(`${result === null ? 'None' : result}\n`);
53	}
54	
55	main();
