1	// Differential harness (parallel): runs the reference executable and the Node
2	// port on the same argv, comparing stdout, stderr (PID-normalized) and exit code.
3	//
4	// Usage:
5	//   node /tmp/difftest.mjs cases.json        # cases.json = [["--a","bc",...], ...]
6	// or import { runAll } and pass an array of argv arrays.
7	import { spawn } from 'node:child_process';
8	
9	const REF = '/workspace/dataset/test4_executable';
10	const PORT_ARGS = ['/output/test4.mjs'];
11	const CONCURRENCY = Number(process.env.DIFF_CONCURRENCY || 24);
12	
13	const norm = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
14	
15	function run(cmd, args) {
16	  return new Promise((resolve) => {
17	    const child = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
18	    let out = '', err = '';
19	    child.stdout.setEncoding('utf8'); child.stderr.setEncoding('utf8');
20	    child.stdout.on('data', (d) => { out += d; });
21	    child.stderr.on('data', (d) => { err += d; });
22	    child.on('error', (e) => resolve({ out, err: String(e), code: -1 }));
23	    child.on('close', (code) => resolve({ out, err, code }));
24	  });
25	}
26	
27	export async function runCase(argv) {
28	  const [a, b] = await Promise.all([run(REF, argv), run('node', [...PORT_ARGS, ...argv])]);
29	  const ok = a.out === b.out && norm(a.err) === norm(b.err) && a.code === b.code;
30	  return { ok, argv, ref: { out: a.out, err: norm(a.err), code: a.code },
31	           port: { out: b.out, err: norm(b.err), code: b.code } };
32	}
33	
34	export async function runAll(cases, { label = '', showMax = 20 } = {}) {
35	  const fails = [];
36	  let pass = 0, next = 0;
37	  async function worker() {
38	    while (next < cases.length) {
39	      const i = next++;
40	      const r = await runCase(cases[i]);
41	      if (r.ok) pass++; else if (fails.length < 500) fails.push(r);
42	    }
43	  }
44	  await Promise.all(Array.from({ length: CONCURRENCY }, worker));
45	  console.log(`[${label}] pass=${pass}/${cases.length} fail=${cases.length - pass}`);
46	  for (const f of fails.slice(0, showMax)) {
47	    console.log('MISMATCH argv=' + JSON.stringify(f.argv));
48	    console.log('  ref : code=' + f.ref.code + ' out=' + JSON.stringify(f.ref.out) + ' err=' + JSON.stringify(f.ref.err));
49	    console.log('  port: code=' + f.port.code + ' out=' + JSON.stringify(f.port.out) + ' err=' + JSON.stringify(f.port.err));
50	  }
51	  return { pass, total: cases.length, fails };
52	}
53	
54	if (process.argv[2]) {
55	  const { readFileSync } = await import('node:fs');
56	  const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
57	  const { fails } = await runAll(cases, { label: process.argv[2] });
58	  process.exit(fails.length ? 1 : 0);
59	}
